package com.jiugeng.erp.watch;
import static org.assertj.core.api.Assertions.assertThat;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;import com.fasterxml.jackson.databind.*;import java.util.*;import org.junit.jupiter.api.*;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.http.MediaType;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.test.context.ActiveProfiles;import org.springframework.test.web.servlet.MockMvc;
@SpringBootTest @AutoConfigureMockMvc @ActiveProfiles("test") class WatchControllerTest{
 static final String PASSWORD="Watch-Test-42";@Autowired MockMvc mvc;@Autowired ObjectMapper json;@Autowired JdbcTemplate jdbc;
 @BeforeEach void reset(){jdbc.update("DELETE FROM watch_new_product_event");jdbc.update("UPDATE watch_store SET baseline_run_id=NULL");jdbc.update("DELETE FROM watch_baseline_asin");jdbc.update("DELETE FROM watch_snapshot_asin");jdbc.update("DELETE FROM watch_run");jdbc.update("DELETE FROM watch_store");jdbc.update("DELETE FROM selection_candidate_evidence");jdbc.update("DELETE FROM selection_candidate_note");jdbc.update("DELETE FROM selection_candidate_tag");jdbc.update("DELETE FROM selection_candidate");jdbc.update("DELETE FROM iam_password_reset_challenge");jdbc.update("DELETE FROM audit_event");jdbc.update("DELETE FROM iam_session");jdbc.update("DELETE FROM iam_user");}
 @Test void safeBaselineDiffAndCandidateTraceSurviveFormalWorkflow()throws Exception{String token=user("watcher","SELECTION");String store=createStore(token,"STORE-A");run(token,store,"run-1","SUCCEEDED",2,1,true,List.of("B0BASE0001","B0BASE0002")).andExpect(jsonPath("$.baselineChanged").value(true)).andExpect(jsonPath("$.events.length()").value(0));String baseline=jdbc.queryForObject("SELECT baseline_run_id FROM watch_store WHERE id=?",String.class,store);
  run(token,store,"run-empty","SUCCEEDED",0,1,true,List.of()).andExpect(jsonPath("$.baselineChanged").value(false)).andExpect(jsonPath("$.run.integrityStatus").value("INCOMPLETE"));assertThat(jdbc.queryForObject("SELECT baseline_run_id FROM watch_store WHERE id=?",String.class,store)).isEqualTo(baseline);
  run(token,store,"run-bad","SUCCEEDED",1,2,false,List.of("B0BASE0001")).andExpect(jsonPath("$.baselineChanged").value(false));assertThat(jdbc.queryForObject("SELECT baseline_run_id FROM watch_store WHERE id=?",String.class,store)).isEqualTo(baseline);
  String response=run(token,store,"run-2","SUCCEEDED",3,1,true,List.of("B0BASE0001","B0BASE0002","B0NEW00001")).andExpect(jsonPath("$.events.length()").value(1)).andReturn().getResponse().getContentAsString();String eventId=json.readTree(response).at("/events/0/id").asText();
  run(token,store,"run-3","SUCCEEDED",3,1,true,List.of("B0BASE0001","B0BASE0002","B0NEW00001")).andExpect(jsonPath("$.events.length()").value(0));assertThat(jdbc.queryForObject("SELECT COUNT(*) FROM watch_new_product_event",Integer.class)).isEqualTo(1);
  String confirmed=mvc.perform(post("/api/v1/watch/events/{id}/confirm",eventId).header("Authorization",bearer(token))).andExpect(status().isOk()).andExpect(jsonPath("$.item.status").value("CONFIRMED")).andReturn().getResponse().getContentAsString();String candidate=json.readTree(confirmed).at("/candidate/id").asText();mvc.perform(post("/api/v1/watch/events/{id}/confirm",eventId).header("Authorization",bearer(token))).andExpect(status().isOk()).andExpect(jsonPath("$.replayed").value(true)).andExpect(jsonPath("$.candidate.id").value(candidate));
  assertThat(jdbc.queryForMap("SELECT source,source_store,source_run_id,source_event_id FROM selection_candidate WHERE id=?",candidate)).containsEntry("SOURCE","WATCH").containsEntry("SOURCE_STORE","监控店铺").containsEntry("SOURCE_EVENT_ID",eventId);assertThat(jdbc.queryForObject("SELECT COUNT(*) FROM audit_event WHERE resource_type='WATCH'",Integer.class)).isGreaterThanOrEqualTo(6);
 }
 @Test void requestIdAndPermissionsAreEnforced()throws Exception{String writer=user("watcher","SELECTION");String store=createStore(writer,"STORE-B");run(writer,store,"same-key","SUCCEEDED",1,1,true,List.of("B0IDEMP0001")).andExpect(jsonPath("$.replayed").value(false));run(writer,store,"same-key","SUCCEEDED",1,1,true,List.of("B0IDEMP0001")).andExpect(jsonPath("$.replayed").value(true));run(writer,store,"same-key","SUCCEEDED",1,1,true,List.of("B0DIFFER001")).andExpect(status().isConflict()).andExpect(jsonPath("$.code").value("WATCH_REQUEST_CONFLICT"));String read=user("product","PRODUCT_MATERIAL");mvc.perform(get("/api/v1/watch/stores").header("Authorization",bearer(read))).andExpect(status().isOk());mvc.perform(post("/api/v1/watch/stores").header("Authorization",bearer(read)).contentType(MediaType.APPLICATION_JSON).content("{\"storeKey\":\"DENIED\",\"storeName\":\"Denied\",\"sourceUrl\":\"https://example.com\"}")).andExpect(status().isForbidden());}
 private String createStore(String token,String key)throws Exception{String body=mvc.perform(post("/api/v1/watch/stores").header("Authorization",bearer(token)).contentType(MediaType.APPLICATION_JSON).content(json.writeValueAsString(Map.of("storeKey",key,"storeName","监控店铺","sourceUrl","https://example.com/store")))).andExpect(status().isOk()).andReturn().getResponse().getContentAsString();return json.readTree(body).get("id").asText();}
 private org.springframework.test.web.servlet.ResultActions run(String token,String store,String request,String status,int count,int pages,boolean complete,List<String> asins)throws Exception{return mvc.perform(post("/api/v1/watch/stores/{id}/runs",store).header("Authorization",bearer(token)).contentType(MediaType.APPLICATION_JSON).content(json.writeValueAsString(Map.of("requestId",request,"status",status,"itemCount",count,"pageCount",pages,"pagesComplete",complete,"asins",asins))));}
 private String user(String name,String role)throws Exception{String id=UUID.randomUUID().toString();var encoder=new org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder();jdbc.update("INSERT INTO iam_user (id,login_name,display_name,password_hash,role,status,must_change_password) VALUES (?,?,?,?,?,'ENABLED',FALSE)",id,name,name,encoder.encode(PASSWORD),role);String body=mvc.perform(post("/api/v1/auth/login").contentType(MediaType.APPLICATION_JSON).content(json.writeValueAsString(Map.of("loginName",name,"password",PASSWORD)))).andExpect(status().isOk()).andReturn().getResponse().getContentAsString();return json.readTree(body).get("token").asText();}private String bearer(String token){return "Bearer "+token;}
}
